    = ffi.Pointer<ffi.NativeFunction<MessageCallbackFunction>>;
typedef MessageCallbackFunction = ffi.Void Function(ffi.Pointer<ffi.Char>);
typedef DartMessageCallbackFunction = void Function(ffi.Pointer<ffi.Char>);

